)

mapper.delete:
DELETE ria FROM receipt_item_allocations ria
JOIN receipt_analysis_items rai ON rai.receipt_analysis_item_id = ria.receipt_analysis_item_id
WHERE rai.receipt_analysis_id = #{receiptAnalysisId}

mapper.insert:
INSERT INTO settlement_item_shares (
    settlement_item_id, settlement_member_id, allocated_quantity, allocated_amount
)
SELECT si.settlement_item_id, sm.settlement_member_id,
       ria.allocated_quantity, ria.allocated_amount
FROM receipt_item_allocations ria
JOIN receipt_analysis_items rai ON rai.receipt_analysis_item_id = ria.receipt_analysis_item_id
JOIN settlement_items si ON si.settlement_id = #{settlementId}
    AND si.source_order = rai.source_order AND si.deleted_at IS NULL
JOIN settlement_members sm ON sm.settlement_id = #{settlementId}
    AND sm.appointment_member_id = ria.appointment_member_id AND sm.deleted_at IS NULL
WHERE rai.receipt_analysis_id = #{receiptAnalysisId}
  AND rai.deleted_at IS NULL AND ria.deleted_at IS NULL

